'use client';

import { motion } from 'motion/react';
import { AnimatedTextSlider } from '../../animated-text-slider';

const AboutHero = () => {
    const tags = [
        { label: 'Curious', color: 'text-cyan-500 dark:text-cyan-400', border: 'border-cyan-500/20 dark:border-cyan-400/20', bg: 'bg-cyan-500/5 dark:bg-cyan-400/5' },
        { label: 'Focused', color: 'text-blue-500 dark:text-blue-400', border: 'border-blue-500/20 dark:border-blue-400/20', bg: 'bg-blue-500/5 dark:bg-blue-400/5' },
        { label: 'Obsessed', color: 'text-purple-500 dark:text-purple-400', border: 'border-purple-500/20 dark:border-purple-400/20', bg: 'bg-purple-500/5 dark:bg-purple-400/5' },
        { label: 'Builder', color: 'text-emerald-500 dark:text-emerald-400', border: 'border-emerald-500/20 dark:border-emerald-400/20', bg: 'bg-emerald-500/5 dark:bg-emerald-400/5' },
    ];

    const stats = [
        { label: 'Location', value: 'Kanpur, India', icon: '📍' },
        { label: 'Experience', value: '1+ Years', icon: '⚡' },
        { label: 'Status', value: 'Available', icon: '🟢' },
    ];

    return (
        <section className="relative pt-12 md:pb-24 pb-16 overflow-hidden">
            {/* Mesh Gradient Background */}
            <div className="absolute top-0 inset-x-0 h-[500px] pointer-events-none">
                <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-400/10 dark:bg-purple-600/5 rounded-full blur-[120px] animate-pulse"></div>
                <div className="absolute bottom-[20%] right-[-5%] w-[30%] h-[30%] bg-cyan-400/10 dark:bg-cyan-600/5 rounded-full blur-[100px] animate-pulse" style={{ animationDelay: '2s' }}></div>
            </div>

            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, ease: "easeOut" }}
                className="space-y-20 relative"
            >
                {/* Heading Section */}
                <div className="space-y-8">
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: 0.1, duration: 0.5 }}
                        className="inline-flex items-center gap-2.5 px-4 py-1.5 rounded-full bg-white/40 dark:bg-white/[0.03] border border-black/[0.08] dark:border-white/[0.08] backdrop-blur-md shadow-sm"
                    >
                        <span className="relative flex h-2 w-2">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                        </span>
                        <span className="text-[11px] font-inter font-medium uppercase tracking-wider text-gray-700 dark:text-gray-300">Open for new projects</span>
                    </motion.div>

                    <div className="space-y-4 max-w-4xl">
                        <h1 className="text-5xl md:text-7xl font-inter font-bold tracking-tight text-gray-900 dark:text-white leading-[1.05]">
                            From a curious kid <br className="hidden md:block" />
                            <span className="text-gray-400 dark:text-zinc-500">to </span>
                            <span className="font-instrument italic font-normal text-gray-900/90 dark:text-white/90">shaping</span>
                        </h1>
                        <AnimatedTextSlider
                            className="text-4xl md:text-5xl font-instrument italic font-normal text-gray-900/90 dark:text-white/90 "
                            texts={["experiences that feel right.", "things people love using.", "products that actually perform."]}
                            interval={3000}
                        />
                    </div>
                </div>

                {/* Main Content Grid */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
                    <div className="lg:col-span-7 space-y-10">
                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            whileInView={{ opacity: 1, y: 0 }}
                            viewport={{ once: true }}
                            transition={{ delay: 0.2, duration: 0.8 }}
                            className="space-y-8"
                        >
                            <div className="space-y-6">
                                <p className="text-xl md:text-2xl text-gray-700 dark:text-zinc-300 font-inter font-light leading-relaxed">
                                    I'm <span className="text-gray-900 dark:text-white font-medium">Shivam</span>, a developer who builds products that people actually want to use. Full-stack by trade, obsessed with making things <span className="italic font-instrument">fast, functional, and good-looking.</span>
                                </p>
                                <p className="text-lg text-gray-500 dark:text-zinc-400 font-inter font-light leading-relaxed">
                                    Right now, I'm freelancing while exploring web3 and blockchain. Smart contracts, decentralized apps—figuring out what's next and how to build it right.
                                </p>
                            </div>

                            <div className="flex flex-wrap gap-2.5 pt-2">
                                {tags.map((tag, index) => (
                                    <motion.span
                                        key={tag.label}
                                        initial={{ opacity: 0, scale: 0.9 }}
                                        whileInView={{ opacity: 1, scale: 1 }}
                                        viewport={{ once: true }}
                                        transition={{ delay: 0.4 + index * 0.1, duration: 0.4 }}
                                        className={`px-4 py-1.5 rounded-xl border ${tag.border} ${tag.bg} ${tag.color} text-[13px] font-medium cursor-default transition-all duration-300 hover:scale-105 hover:shadow-lg`}
                                    >
                                        {tag.label}
                                    </motion.span>
                                ))}
                            </div>
                        </motion.div>
                    </div>

                    <div className="lg:col-span-5">
                        <motion.div
                            initial={{ opacity: 0, x: 20 }}
                            whileInView={{ opacity: 1, x: 0 }}
                            viewport={{ once: true }}
                            transition={{ delay: 0.4, duration: 0.8 }}
                            className="group relative"
                        >
                            {/* Card Glow Effect */}
                            <div className="absolute -inset-0.5 bg-linear-to-r from-gray-200 to-gray-200 dark:from-zinc-800 dark:to-zinc-800 rounded-[2.5rem] blur opacity-10 group-hover:opacity-20 transition duration-1000"></div>

                            <div className="relative p-8 rounded-[2rem] border border-black/[0.04] dark:border-white/[0.04] bg-white/60 dark:bg-black/40 backdrop-blur-2xl shadow-[0_8px_32px_-4px_rgba(0,0,0,0.04)] dark:shadow-none space-y-8">
                                <h3 className="text-xs font-mono uppercase tracking-[0.2em] text-gray-400 dark:text-zinc-500 border-b border-black/[0.04] dark:border-white/[0.04] pb-4">
                                    Snapshot
                                </h3>

                                <div className="space-y-8">
                                    {stats.map((stat, i) => (
                                        <div key={stat.label} className="flex items-center gap-5 group/item">
                                            <div className="w-12 h-12 rounded-2xl bg-black/[0.03] dark:bg-white/[0.03] flex items-center justify-center text-xl transition-transform duration-300 group-hover/item:scale-110 group-hover/item:rotate-3">
                                                {stat.icon}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="text-[10px] font-mono uppercase tracking-[0.15em] text-gray-400 dark:text-zinc-500 mb-0.5">
                                                    {stat.label}
                                                </span>
                                                <span className="text-base font-medium text-gray-900 dark:text-white tracking-tight">
                                                    {stat.value}
                                                </span>
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                <div className="pt-4">
                                    <div className="h-px w-full bg-linear-to-r from-transparent via-black/[0.05] dark:via-white/[0.05] to-transparent"></div>
                                    <p className="text-[10px] text-center text-gray-400 dark:text-zinc-600 font-mono mt-4 uppercase tracking-widest">
                                        Last updated Jan 2026
                                    </p>
                                </div>
                            </div>
                        </motion.div>
                    </div>
                </div>
            </motion.div>
        </section>
    );
};

export default AboutHero;


