'use client';

import React from 'react';
import { motion } from 'motion/react';
import Image from 'next/image';
import { Swords, Gamepad2, Tv } from 'lucide-react';

import ufcImg from '../../../assets/ufc.png';
import ffImg from '../../../assets/freefire.png';
import wsImg from '../../../assets/webseries.png';

const BeyondCode = () => {
    const interests = [
        {
            title: "UFC Enthusiast",
            description: "Nothing beats the adrenaline of a main event fight night. I'm deep into the technique and the sheer grit of MMA.",
            image: ufcImg,
            icon: <Swords className="w-5 h-5" />,
            color: "from-red-500/20 to-zinc-950",
            accent: "text-red-400",
            border: "border-red-400/20",
            glow: "group-hover:shadow-[0_0_40px_-10px_rgba(239,68,68,0.3)]"
        },
        {
            title: "Free Fire Survivor",
            description: "Strategy, fast reflexes, and clearing the lobby is my way of unwinding. Always chasing that Booyah zone.",
            image: ffImg,
            icon: <Gamepad2 className="w-5 h-5" />,
            color: "from-cyan-500/20 to-zinc-950",
            accent: "text-cyan-400",
            border: "border-cyan-400/20",
            glow: "group-hover:shadow-[0_0_40px_-10px_rgba(34,211,238,0.3)]"
        },
        {
            title: "Cinephile & Series",
            description: "Lost in complex narratives and cinematic storytelling. It's where I find inspiration for visual rhythm and pacing.",
            image: wsImg,
            icon: <Tv className="w-5 h-5" />,
            color: "from-purple-500/20 to-zinc-950",
            accent: "text-purple-400",
            border: "border-purple-400/20",
            glow: "group-hover:shadow-[0_0_40px_-10px_rgba(168,85,247,0.3)]"
        }
    ];

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: { staggerChildren: 0.2 }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 30, filter: 'blur(10px)' },
        visible: {
            opacity: 1,
            y: 0,
            filter: 'blur(0px)',
            transition: { duration: 0.8, ease: [0.22, 1, 0.36, 1] }
        }
    };

    return (
        <section className="space-y-16 py-20 relative">
            {/* Background Accent */}
            <div className="absolute top-0 right-0 -z-10 w-64 h-64 bg-zinc-200 dark:bg-zinc-800/10 rounded-full blur-[100px] opacity-20"></div>

            {/* Header */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                className="space-y-4 max-w-2xl"
            >
                <div className="flex items-center gap-3">
                    <div className="h-px w-8 bg-black/10 dark:bg-white/10"></div>
                    <span className="text-[11px] font-mono tracking-[0.3em] uppercase text-gray-400 dark:text-zinc-500">
                        Persona
                    </span>
                </div>
                <h2 className="text-4xl md:text-6xl font-inter font-bold text-gray-900 dark:text-white tracking-tight leading-tight">
                    Beyond <span className="font-instrument italic font-normal text-gray-500 dark:text-zinc-500">the keyboard.</span>
                </h2>
                <p className="text-base text-gray-500 dark:text-zinc-400 font-inter font-light max-w-lg leading-relaxed">
                    When the laptop shuts down, these are the worlds I step into to recharge, compete, and find fresh perspective.
                </p>
            </motion.div>

            {/* Grid */}
            <motion.div
                variants={containerVariants}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                className="grid grid-cols-1 md:grid-cols-3 gap-8"
            >
                {interests.map((interest, index) => (
                    <motion.div
                        key={interest.title}
                        variants={itemVariants}
                        className={`group relative h-[500px] rounded-[2.5rem] overflow-hidden border border-black/[0.08] dark:border-white/[0.08] bg-zinc-50 dark:bg-zinc-900 shadow-sm transition-all duration-500 ${interest.glow} hover:-translate-y-2`}
                    >
                        {/* Background Image & Overlay */}
                        <div className="absolute inset-0 transition-transform duration-1000 ease-out group-hover:scale-110">
                            <Image
                                src={interest.image}
                                alt={interest.title}
                                fill
                                className="object-cover opacity-80 grayscale-[0.2] transition-all duration-700 brightness-[0.85] dark:brightness-75 group-hover:grayscale-0 group-hover:brightness-100"
                            />
                            {/* Gradient Mask */}
                            <div className={`absolute inset-0 bg-linear-to-t ${interest.color} via-zinc-950/40 to-transparent opacity-90 transition-opacity duration-500`} />

                            {/* Noise Texture */}
                            <div className="absolute inset-0 opacity-[0.03] pointer-events-none mix-blend-overlay bg-[url('https://grainy-gradients.vercel.app/noise.svg')]"></div>
                        </div>

                        {/* Content Overlay */}
                        <div className="relative h-full p-8 flex flex-col justify-end">
                            <div className="translate-y-12 group-hover:translate-y-0 transition-transform duration-500 ease-out space-y-5">
                                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center bg-white/10 backdrop-blur-xl border ${interest.border} ${interest.accent} shadow-2xl transition-transform duration-500 group-hover:scale-110 group-hover:rotate-3`}>
                                    {interest.icon}
                                </div>
                                <div className="space-y-3">
                                    <h3 className="text-3xl font-instrument italic text-white leading-tight">
                                        {interest.title}
                                    </h3>
                                    <p className="text-sm font-inter font-light text-zinc-300/0 group-hover:text-zinc-300 leading-relaxed transition-all duration-500 opacity-0 group-hover:opacity-100 delay-100">
                                        {interest.description}
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Top Accent Light */}
                        <div className="absolute top-0 inset-x-0 h-32 bg-linear-to-b from-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
                    </motion.div>
                ))}
            </motion.div>
        </section>
    );
};

export default BeyondCode;
